using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;using System.Linq;
[InitializeOnLoad]public static class CubeDrawerSlideSetup{
 static CubeDrawerSlideSetup(){EditorApplication.delayCall+=Apply;EditorSceneManager.sceneSaved+=s=>EditorApplication.delayCall+=Apply;}
 [MenuItem("Tools/JIQI/Bind Cube Drawer Slides")]public static void Apply(){if(EditorApplication.isCompiling||EditorApplication.isUpdating){EditorApplication.delayCall+=Apply;return;}if(EditorApplication.isPlayingOrWillChangePlaymode)return;var scene=SceneManager.GetActiveScene();if(!scene.IsValid()||scene.name.Replace(" ","").ToLowerInvariant()!="scene2")return;var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();int before=all.Sum(t=>t.GetComponents<CubeDrawerSlide>().Length+t.GetComponents<MeshCollider>().Length);CubeDrawerSlide.Bind(scene);int after=all.Sum(t=>t.GetComponents<CubeDrawerSlide>().Length+t.GetComponents<MeshCollider>().Length);foreach(var t in all){var slide=t.GetComponent<CubeDrawerSlide>();if(slide){EditorUtility.SetDirty(slide);PrefabUtility.RecordPrefabInstancePropertyModifications(slide);}}if(before!=after){EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);}}
}
